mapper.select:
select id, card_id, user_id, direction, state, step, stability, difficulty, next_review_date, last_review_date,
       reps, lapses, last_rating, first_learned_date, mastered_at, updated_at
from pw_card_progress
where user_id = #{userId}
  and card_id = #{cardId}
  and direction = #{direction}
limit 1

select id, card_id, user_id, direction, state, step, stability, difficulty, next_review_date, last_review_date,
       reps, lapses, last_rating, first_learned_date, mastered_at, updated_at
from pw_card_progress
where user_id = #{userId}
  and card_id = #{cardId}
order by direction asc

select id, card_id, user_id, direction, state, step, stability, difficulty, next_review_date, last_review_date, reps, lapses, last_rating, first_learned_date, mastered_at, updated_at from pw_card_progress where user_id = #{userId} and card_id in
#{id}
order by card_id asc, direction asc

mapper.insert:
insert into pw_card_progress (
    card_id, user_id, direction, state, step, stability, difficulty, next_review_date,
    last_review_date, reps, lapses, last_rating, first_learned_date, mastered_at
) values (
    #{cardId}, #{userId}, #{direction}, #{state}, #{step}, #{stability}, #{difficulty}, #{nextReviewDate},
    #{lastReviewDate}, #{reps}, #{lapses}, #{lastRating}, #{firstLearnedDate}, #{masteredAt}
)

mapper.select:
select count(*)
from (
    select distinct cp.card_id, cp.direction
    from pw_card_progress cp
    inner join pw_card c on c.id = cp.card_id
    where cp.user_id = #{userId}
      and cp.last_review_date = #{today}
      and c.deck_id = #{deckId}
) t
